    /// Whether the app that carries this assistant's name is the wrong thing to show for it.
    static let preferredOverApp: Set<String> = ["claude", "codex"]

    static func has(_ id: String) -> Bool { glyphs[id] != nil }

    /// The tile, rendered as a vector image: it stays sharp at every size a row asks for.
    @MainActor
    static func image(for id: String, hue: UInt32) -> NSImage? {
        guard let glyph = glyphs[id] else { return nil }
        let color = String(format: "#%06X", hue)
        let svg = """
        <svg xmlns="http://www.w3.org/2000/svg" width="96" height="96" viewBox="0 0 24 24">
        <rect width="24" height="24" rx="6.2" fill="\(color)" fill-opacity="0.16"/>
        <rect x="0.25" y="0.25" width="23.5" height="23.5" rx="5.95" fill="none" stroke="\(color)" stroke-opacity="0.32" stroke-width="0.5"/>
        <g transform="translate(4.6 4.6) scale(0.62)"><path fill="\(color)" \(glyph.evenOdd ? "fill-rule=\"evenodd\" " : "")d="\(glyph.path)"/></g>
        </svg>
        """
        guard let image = NSImage(data: Data(svg.utf8)) else { return nil }
        image.size = NSSize(width: 32, height: 32)
        return image
    }
}
